3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import tools.jackson.databind.node.ObjectNode;
6	
7	/** membership-points: points = +2 email, +1 namesake 0, +2 household of 3+, +3 tenure over
8	 * 365 days; mapped to level 1 (0-1) / 2 (2-3) / 3 (4-5) / 4 (6+). A fresh owner with an email and
9	 * no namesake scores 3 points (2 + 1), a single-member household, zero tenure -> level 2. */
10	class AcceptanceTest extends AcceptanceBase {
11	
12		@Test
13		void coreReturnsPointsAndLevel() throws Exception {
14			ObjectNode o = withPostcode(ownerNode());
15			o.put("email", uniqueEmail());
16			int id = createOwnerOk(o);
17			getOwner(id).andExpect(jsonPath("$.membershipPoints").value(3))
18					.andExpect(jsonPath("$.membershipLevel").value(2));
19		}
20	}
