16	
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
27	    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
28	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
29	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
31	    @Mapping(target = "identityKey", expression = "java(toIdentityKey(owner))")
32	    @Mapping(target = "checkDigit", expression = "java(toCheckDigit(owner))")
33	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /**
37	     * The owner's age band, derived by {@link AgeBand} from the owner's {@code birthDate}
38	     * against the effective {@code registrationDate}. {@code null} when the owner has no
39	     * birthDate (or no registrationDate to compute against).
40	     */
41	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
42	        AgeBand band = AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate());
43	        return (band == null) ? null : OwnerDto.AgeBandEnum.valueOf(band.name());
44	    }
45	
46	    /**
47	     * A single Luhn check digit (0-9) computed over the digits of the owner's
48	     * {@code customerCode}. {@code null} when the owner has no customer code.
49	     */
50	    default Integer toCheckDigit(Owner owner) {
51	        return LuhnCheckDigit.of(owner.getCustomerCode());
52	    }
53	
54	    /**
55	     * The owner's derived identityKey — the single value all duplicate detection is
56	     * expressed through. See {@link OwnerIdentity}.
57	     */
58	    default String toIdentityKey(Owner owner) {
59	        return OwnerIdentity.of(owner);
60	    }
61	
62	    /**
63	     * The owner's locality: the region derived from the postcode by the shared
64	     * {@link CityRegions} table (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or 'UNKNOWN' when
65	     * the postcode is absent or in no known range. This is the same value as the {@code <REGION>}
66	     * prefix of the owner's {@code customerCode}, so the locality follows the region-and-hash
67	     * identity rather than the city.
68	     */
69	    default String toLocality(Owner owner) {
70	        return CityRegions.identityRegion(owner.getPostcode());
71	    }
72	
73	    /**
74	     * The owner's preferred contact channel: 'EMAIL' when an email is present,
75	     * otherwise 'PHONE'.
76	     */
77	    default OwnerDto.ContactPreferenceEnum toContactPreference(Owner owner) {
78	        String email = owner.getEmail();
79	        return (email != null && !email.isBlank())
80	                ? OwnerDto.ContactPreferenceEnum.EMAIL
81	                : OwnerDto.ContactPreferenceEnum.PHONE;
82	    }
83	
84	    /**
85	     * The stored E.164 telephone formatted for humans by the shared {@link OwnerTelephones}
86	     * rule: country code, a space, then the national digits grouped in threes.
87	     */
88	    default String toTelephoneDisplay(Owner owner) {
89	        return OwnerTelephones.toDisplay(owner.getTelephone());
90	    }
91	
92	    /** The owner's name formatted as 'LastName, FirstName'. */
93	    default String toDisplayName(Owner owner) {
94	        return owner.getLastName() + ", " + owner.getFirstName();
95	    }
96	
97	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
98	    default String toInitials(Owner owner) {
99	        return owner.getFirstName().substring(0, 1).toUpperCase()
100	                + "." + owner.getLastName().substring(0, 1).toUpperCase() + ".";
101	    }
102	
103	    Owner toOwner(OwnerDto ownerDto);
104	
105	    @Mapping(target = "id", ignore = true)
106	    @Mapping(target = "pets", ignore = true)
107	    @Mapping(target = "customerCode", ignore = true)
108	    @Mapping(target = "householdId", ignore = true)
109	    @Mapping(target = "namesakeCount", ignore = true)
110	    @Mapping(target = "membershipNumber", ignore = true)
111	    @Mapping(target = "bulkSignupWarning", ignore = true)
112	    Owner toOwner(OwnerFieldsDto ownerDto);
113	
114	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
115	
116	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
117	
118	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
119	        OwnerPageDto ownerPageDto = new OwnerPageDto();
120	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
